[CmdletBinding()]
param([Parameter(Mandatory)][string]$Command,[string]$OutputRoot='performance/reports/r9-runs',[int]$Repetitions=5,[int]$WarmupSeconds=15,[int]$SampleSeconds=30,[int]$RenderDistance=16,[string[]]$SceneIds=@('01','02','03','04','05','06','07','08'),[switch]$DryRun)
$ErrorActionPreference='Stop';if($Repetitions -lt 1 -or $RenderDistance -ne 16){throw 'R9 protocol requires repetitions >= 1 and render distance exactly 16'};New-Item -ItemType Directory -Force $OutputRoot|Out-Null
foreach($scene in $SceneIds){for($rep=1;$rep -le $Repetitions;$rep++){ $dir=Join-Path $OutputRoot "scene-$scene/rep-$rep";New-Item -ItemType Directory -Force $dir|Out-Null;$meta=[ordered]@{schema='icraft.r9.run.v1';sceneId=$scene;repetition=$rep;renderDistance=$RenderDistance;warmupSeconds=$WarmupSeconds;sampleSeconds=$SampleSeconds;capturedUtc=[DateTime]::UtcNow.ToString('o');command=$Command};$meta|ConvertTo-Json|Set-Content (Join-Path $dir 'run.json') -Encoding utf8;$args=@('--scene',$scene,'--render-distance',$RenderDistance,'--warmup-seconds',$WarmupSeconds,'--sample-seconds',$SampleSeconds,'--output-jsonl',(Join-Path $dir 'frames.jsonl'));if(!$DryRun){& $Command @args;if($LASTEXITCODE -ne 0){throw "Command failed for scene $scene repetition $rep ($LASTEXITCODE)"}}else{Write-Output (($Command+' '+($args -join ' ')))}}}
